INSERT INTO sanpham (id, tensanpham, mota, giagoc, giaban, soluongton, hinhanh, danhmuc_id, thuonghieu_id, doituong, sizes, mausac, chatlieu, thanhphan, muctieu, hansudung, noibat, trangthai, luotxem, luotmua) VALUES
(8, 'Áo Thun Tập Gym Nam Under Armour Tech 2.0', 'Áo thun tập gym nam Under Armour Tech 2.0 mang đến cảm giác tập luyện nhẹ tênh và thông thoáng tối đa. Ứng dụng công nghệ sợi vải UA Tech độc quyền siêu mềm mượt, mô phỏng cảm giác sợi tự nhiên nhưng sở hữu tốc độ khô ráo nhanh gấp 3 lần cotton thông thường. Phom áo Regular thể thao vừa vặn, không quá bó sát cũng không quá rộng thùng thình, tôn lên bờ vai và bắp tay săn chắc. Thiết kế đường may vai công thái học dời về phía trước, loại bỏ hoàn toàn cảm giác cọ xát gồ ghề khi gánh tạ đòn Squat hay vác đòn tạ trên vai.\n\nPhù hợp cho các buổi tập nâng tạ, chạy bộ, cardio, chơi thể thao bóng rổ, tennis hoặc mặc hàng ngày phong cách năng động.\n\nBẢO QUẢN CHUẨN GYMER:\n- Giặt máy bằng nước lạnh dưới 30°C cùng màu tương tự.\n- Không sử dụng chất làm mềm vải (nước xả) để tránh làm bít tắc các vi lỗ thoáng khí trên sợi UA Tech.\n- Sấy ở nhiệt độ thấp hoặc phơi trong bóng râm, không ủi/là trực tiếp lên áo.', 650000, 520000, 45, 'ao_nam_ua_tech.jpg', 1, 5, 'nam', 'S,M,L,XL', 'Đen,Xám,Xanh Navy', '100% Polyester', NULL, 'tangcan,duytri', NULL, 0, 1, 236, 86),
(9, 'Áo Tank Top Gym Nam Gymshark Critical', 'Áo Tank Top gym nam Gymshark Critical là biểu tượng quen thuộc của các gymer theo đuổi phong cách Hardcore Bodybuilding. Thiết kế vạt áo xẻ tà nhẹ cùng phần khoét nách sâu (Drop-armhole) giúp giải phóng toàn bộ khớp vai và cơ xô khi thực hiện các bài kéo tạ lưng (Pull-down, Row) hoặc đẩy vai (Overhead Press). Chất vải Cotton chải kỹ kết hợp Elastane co giãn linh hoạt, mang lại độ êm ái tối đa cho da, độ thấm hút mồ hôi cực tốt và giữ form áo chuẩn sau nhiều lần giặt.\n\nMặc trong các buổi tập tạ cường độ cao, đặc biệt là các ngày tập Lưng - Xô (Pull Day), Ngực - Vai (Push Day) để dễ dàng quan sát cơ bắp co giãn trong gương.\n\nBẢO QUẢN CHUẨN GYMER:\n- Giặt với nước lạnh, giặt tay hoặc dùng túi giặt khi giặt máy.\n- Lộn trái áo trước khi phơi, giũ phẳng áo để hạn chế nếp nhăn tự nhiên của sợi cotton.\n- Không ngâm trong chất tẩy rửa mạnh.', 480000, 390000, 50, 'ao_nam_gymshark_tank.jpg', 1, 1, 'nam', 'S,M,L,XL', 'Đen,Trắng,Xám Đậm', 'Cotton pha Polyester', NULL, 'tangcan,duytri', NULL, 0, 1, 133, 32),
(10, 'Áo Thun Tập Luyện Nam Adidas Aeroready', 'Áo thun tập luyện nam Adidas Aeroready ứng dụng công nghệ thấm hút ẩm Aeroready tân tiến, giữ cho cơ thể bạn luôn khô ráo và tập trung cao độ trong suốt buổi tập. Chất liệu 100% Polyester tái chế thân thiện với môi trường, dệt theo cấu trúc mắt lưới siêu nhỏ gia tăng lưu thông gió. Đường cắt FreeLift thông minh giúp áo cố định hoàn hảo, không bị hớt tà lên khi thực hiện các động tác giơ cao tay như Pull-up, Shoulder Press hay nhảy Jumping Jack.\n\nLý tưởng cho các bài tập Cardio, HIIT đốt mỡ, tập tạ với máy, chạy bộ trong nhà và ngoài trời.\n\nBẢO QUẢN CHUẨN GYMER:\n- Giặt máy ở chế độ nhẹ với nước lạnh, không giặt khô.\n- Không dùng chất tẩy trắng chứa clo.\n- Phơi khô tự nhiên trên dây phơi hoặc móc treo nơi thoáng gió.', 590000, 450000, 55, 'ao_nam_adidas_aeroready.jpg', 1, 6, 'nam', 'S,M,L,XL', 'Đen,Xanh Than,Xám', '100% Polyester tái chế', NULL, 'giamcan,duytri', NULL, 0, 1, 125, 29),
(11, 'Áo Bra Tập Gym Nữ Nike Pro Indy', 'Áo Sport Bra tập gym nữ Nike Pro Indy mang đến sự nâng đỡ nhẹ nhàng (Light Support) và cảm giác tự do tối đa cho phái đẹp. Thiết kế dây đeo vai mảnh mai đan chéo sau lưng đầy nữ tính, giúp giải phóng toàn bộ chuyển động của bả vai và cột sống. Công nghệ vải Nike Dri-FIT kết hợp sợi Spandex cao cấp thấm hút mồ hôi siêu tốc. Đi kèm miếng đệm mút ngực có thể tháo rời dễ dàng, hỗ trợ định hình form ngực tự nhiên và kín đáo dưới mọi trang phục tập luyện.\n\nPhù hợp hoàn hảo cho các bộ môn cường độ thấp đến vừa như Yoga, Pilates, Barre, đi bộ dốc máy treadmill hoặc tập tạ nhẹ nhóm cơ phụ.\n\nBẢO QUẢN CHUẨN GYMER:\n- Tháo rời 2 miếng mút đệm ngực trước khi giặt để giữ đệm không bị xô lệch hoặc gãy nếp.\n- Giặt tay với xà phòng dịu nhẹ hoặc giặt máy trong túi giặt đồ lót.\n- Phơi ngang trong bóng râm, không dùng kẹp kẹp mạnh vào quai áo.', 790000, 650000, 40, 'bra_nu_nike_indy.jpg', 1, 2, 'nu', 'S,M,L,XL', 'Đen,Hồng Phấn,Trắng', 'Polyester Dri-FIT pha Spandex', NULL, 'giamcan,duytri', NULL, 1, 1, 86, 29),
(12, 'Áo Croptop Tập Gym Nữ Gymshark Training', 'Áo Croptop tập gym nữ Gymshark Training được thiết kế ôm sát cơ thể với độ dài ngang rốn chuẩn mực, khoe trọn vòng eo thon gọn và cơ bụng săn chắc. Vải dệt kim kết hợp Nylon và Elastane co giãn 4 chiều mềm mịn, hỗ trợ từng nhịp thở và chuyển động uốn dẻo linh hoạt. Cổ áo bo tròn ôm vừa vặn, phần nách áo khoét tinh tế chống lộ dây bra bên trong, mang đến diện mạo thể thao hiện đại, tự tin cho các cô nàng mê gym.\n\nPhối hoàn hảo cùng quần Legging cạp cao hoặc quần Short thể thao trong các buổi tập gym, cardio, đạp xe hoặc nhảy hiện đại.\n\nBẢO QUẢN CHUẨN GYMER:\n- Giặt bằng nước lạnh, lộn trái áo khi giặt để bảo vệ màu sắc và bề mặt vải.\n- Không vắt xoắn mạnh, giũ nhẹ trước khi phơi.\n- Tránh phơi trực tiếp dưới ánh nắng mặt trời giữa trưa.', 520000, 420000, 38, 'croptop_nu_gymshark.jpg', 1, 1, 'nu', 'S,M,L,XL', 'Đen,Tím,Xanh Mint', 'Nylon pha Elastane', NULL, 'giamcan,duytri', NULL, 0, 1, 117, 42),
(13, 'Quần Short Tập Gym Nam Under Armour Tech', 'Quần short tập gym nam Under Armour Tech được thiết kế với chiều dài ống 9 inch chuẩn trên gối, tối ưu cho các chuyển động nâng tạ và vận động thể lực. Chất liệu vải dệt UA Tech độc quyền siêu nhẹ, thoáng khí và có khả năng thoát ẩm siêu tốc. Cạp thun co giãn mật độ cao tích hợp dây rút ẩn bên trong giúp cố định cạp quần chắc chắn. Hai túi hở bên hông sâu và rộng, lót lưới thông gió giúp cất giữ nhanh phụ kiện tập luyện.\n\nSử dụng cho các buổi tập thể hình toàn thân, tập chân, chạy bộ, cardio hoặc mặc ở nhà thư giãn sau tập.\n\nBẢO QUẢN CHUẨN GYMER:\n- Giặt với nước lạnh, tránh giặt chung với quần áo có khóa dán nhám (Velcro) để tránh xước vải.\n- Không dùng nước xả vải làm giảm tính năng thoát ẩm.\n- Phơi nơi khô ráo, thoáng mát.', 520000, 420000, 48, 'quan_nam_ua_short.jpg', 2, 5, 'nam', 'S,M,L,XL', 'Đen,Xám,Xanh Navy', '100% Polyester', NULL, 'giamcan,tangcan,duytri', NULL, 0, 1, 185, 63),
(14, 'Quần Jogger Tập Gym Nam Nike Dri-FIT', 'Quần jogger tập gym nam Nike Dri-FIT kết hợp hoàn hảo giữa phong cách thể thao đường phố hiện đại và hiệu năng tập luyện đỉnh cao. Sử dụng chất vải thun dệt công nghệ Dri-FIT dày dặn vừa phải, mặt trong mềm mại giữ ấm cơ bắp khi khởi động buổi sáng sớm, mặt ngoài thoát ẩm cực nhanh khi cơ thể tăng nhiệt. Phom quần ôm nhẹ từ đùi xuống gấu bo thun (tapered-fit), khoe trọn đôi giày thể thao năng động và không gây vướng víu vào máy tập.\n\nMặc khi khởi động, tập gym trong phòng điều hòa lạnh, chạy bộ buổi sớm, tập ngoài trời mùa lạnh hoặc dạo phố.\n\nBẢO QUẢN CHUẨN GYMER:\n- Giặt bằng nước lạnh, lộn trái quần trước khi cho vào máy giặt.\n- Giặt cùng đồ màu tối tương tự để tránh lem màu.\n- Không ủi nhiệt độ cao lên phần bo gấu và logo.', 950000, 790000, 30, 'quan_nam_nike_jogger.jpg', 2, 2, 'nam', 'S,M,L,XL', 'Đen,Xám Đậm', 'Polyester Dri-FIT', NULL, 'tangcan,duytri', NULL, 0, 1, 46, 13),
(15, 'Quần Short Tập Luyện Nam Adidas Designed 4 Training', 'Quần short tập luyện nam Adidas Designed 4 Training (D4T) là sản phẩm cao cấp chuyên dụng cho các bài tập nặng đòi hỏi sự cơ động tối đa. Vải dệt co giãn nhẹ từ Polyester tái chế pha Elastane dẻo dai, tích hợp đường xẻ tà công thái học hai bên hông giúp chuyển động mở khớp háng khi Deep Squat mượt mà không hề bị căng kích. Túi khóa kéo sau lưng và hai bên hông giúp bảo vệ điện thoại, tai nghe và chìa khóa tủ an toàn.\n\nChuyên dùng cho ngày tập chân (Leg Day), Squat, Deadlift, tập xà, tập tạ nặng và bài tập thể lực cường độ cao.\n\nBẢO QUẢN CHUẨN GYMER:\n- Đóng tất cả các dây khóa kéo trước khi giặt máy.\n- Giặt ở chu kỳ nhẹ với nước lạnh.\n- Phơi khô tự nhiên trong bóng mát.', 650000, 520000, 41, 'quan_nam_adidas_short.jpg', 2, 6, 'nam', 'S,M,L,XL', 'Đen,Xanh Than', 'Polyester tái chế pha Elastane', NULL, 'giamcan,tangcan,duytri', NULL, 0, 1, 100, 21),
(16, 'Quần Legging Nữ Gymshark Vital Seamless', 'Quần Legging nữ Gymshark Vital Seamless là sản phẩm huyền thoại được hàng triệu gymer nữ yêu thích trên toàn cầu. Công nghệ dệt không đường may (Seamless) đa mật độ ôm siết nhẹ nhàng từng bó cơ đùi, nâng đỡ vòng 3 căng tròn tự nhiên mà không gây lằn vết trên da. Cạp quần dệt gân nén cao ôm gọn vùng mỡ bụng dưới, cố định vị trí không bị tuột cạp khi vận động. Chất vải siêu dày dặn đạt chuẩn Squat-Proof 100%, bảo vệ sự riêng tư tối đa dưới mọi góc độ.\n\nTuyệt vời cho các bài tập mông đùi (Glutes & Hamstrings), Squat, Hip Thrust, Yoga, Pilates và Cardio.\n\nBẢO QUẢN CHUẨN GYMER:\n- Giặt máy trong túi giặt chuyên dụng với nước lạnh dưới 30°C.\n- Không ngâm quần với bột giặt có tính tẩy rửa mạnh.\n- Phơi ngang trên dây phơi trong bóng râm, không dùng kẹp nhọn làm rách sợi dệt.', 1050000, 850000, 36, 'legging_nu_gymshark_vital.jpg', 2, 1, 'nu', 'S,M,L,XL', 'Đen,Hồng Pastel,Xám', 'Nylon pha Elastane', NULL, 'giamcan,duytri', NULL, 1, 1, 126, 49),
(17, 'Quần Legging Nữ Adidas Optime Training', 'Quần Legging nữ Adidas Optime Training mang lại sự hỗ trợ liên tục từ hiệp tập đầu tiên đến hiệp tập cuối cùng. Vải công nghệ bốn chiều Adimove co giãn vượt trội, ôm khít cơ thể và giữ nguyên form dáng sau hàng trăm lần giặt. Cạp cao liền mạch bản rộng giữ cố định vòng eo, túi nhỏ ẩn tiện lợi trong cạp quần giúp đựng chìa khóa hoặc thẻ phòng tập gọn gàng. Công nghệ Aeroready kiểm soát độ ẩm tối ưu giúp bạn luôn thoải mái và tự tin.\n\nThích hợp cho tập Gym, chạy bộ đường dài, các lớp tập nhảy Dance, Yoga và rèn luyện thể chất dẻo dai.\n\nBẢO QUẢN CHUẨN GYMER:\n- Giặt với nước lạnh, giặt cùng các trang phục đồng màu.\n- Không sấy khô bằng máy sấy nhiệt cao.\n- Phơi nơi khô ráo, thoáng mát.', 1100000, 890000, 34, 'legging_nu_adidas_optime.jpg', 2, 6, 'nu', 'S,M,L,XL', 'Đen,Xanh Than', 'Polyester tái chế pha Elastane', NULL, 'giamcan,duytri', NULL, 0, 1, 267, 89),
(18, 'Quần Short Tập Gym Nữ Nike Pro 3 Inch', 'Quần short tập gym nữ Nike Pro 3 Inch mang phong cách thể thao khỏe khoắn và gợi cảm, là sự lựa chọn số 1 của các vận động viên chuyên nghiệp. Độ dài ống 3 inch linh hoạt tối đa, có thể mặc riêng biệt hoặc mặc lót trong quần short thể thao rộng. Chất vải thun nén nhẹ Nike Pro kết hợp công nghệ Dri-FIT thấm mồ hôi siêu tốc. Cạp thun bản to ôm êm ái quanh hông, đặc biệt thiết kế mép viền đùi chống cuộn gập khi gập chân hoặc nhảy dây.\n\nMặc trong các buổi tập mông đùi, tập chạy nước rút, tập nhảy dây, tập HIIT hoặc mặc lót bảo hộ bên trong.\n\nBẢO QUẢN CHUẨN GYMER:\n- Giặt nhẹ nhàng với nước lạnh, tránh cọ xát với các bề mặt nhám.\n- Không sử dụng nước xả vải.\n- Phơi trong bóng râm thoáng mát.', 620000, 490000, 40, 'quan_nu_nike_pro_short.jpg', 2, 2, 'nu', 'S,M,L,XL', 'Đen,Xám,Xanh Dương', 'Polyester pha Spandex', NULL, 'giamcan,tangcan,duytri', NULL, 0, 1, 295, 115),
(19, 'Găng Tay Tập Gym Harbinger Pro Có Quấn Cổ Tay', 'Găng tay tập gym Harbinger Pro Có Quấn Cổ Tay là dòng găng bảo hộ cao cấp từ thương hiệu phụ kiện thể hình số 1 thế giới. Lòng bàn tay lót da tổng hợp thật tích hợp đệm xốp êm ái, bảo vệ lòng bàn tay khỏi chai sần và giảm áp lực đè nén từ thanh đòn tạ. Đai quấn cổ tay dài bản rộng may liền khóa dán chắc chắn giúp cố định vững vàng khớp cổ tay, duy trì đúng góc độ khớp khi thực hiện các bài đẩy ngực và đẩy vai nặng.\n\nĐeo găng trước khi tập các bài đẩy tạ (Press), kéo tạ (Pull), xà đơn, đẩy ngực với tạ đòn hoặc tạ đơn.\n\nBẢO QUẢN CHUẨN GYMER:\n- Sau khi tập, mở rộng đai quấn và để nơi khô thoáng để bay hết mồ hôi bên trong.\n- Giặt tay với nước ấm và xà phòng loãng mỗi 2 tuần một lần.\n- Phơi khô tự nhiên trong bóng mát, không phơi trực tiếp dưới ánh nắng gay gắt.', 480000, 390000, 45, 'gang_tay_harbinger_pro.jpg', 3, 7, 'unisex', 'S,M,L,XL', 'Đen,Đen Đỏ', 'Da tổng hợp, lưới thoáng, đệm xốp', NULL, 'tangcan,duytri', NULL, 0, 1, 83, 28),
(20, 'Đai Lưng Tập Tạ Harbinger 4 Inch', 'Đai lưng tập tạ Harbinger 4 Inch là phụ kiện bắt buộc phải có cho các gymer muốn nâng cao mức tạ mà vẫn đảm bảo an toàn tuyệt đối cho cột sống. Thiết kế bản rộng 4 inch chuẩn thi đấu, lõi đệm xốp đặc siêu nén bọc vải nylon chịu lực dẻo dai, nâng đỡ vững chãi toàn bộ vùng lưng dưới và khoang bụng. Khóa dán Velcro hạng nặng kết hợp con lăn thép không gỉ trượt êm ái, cho phép siết chặt hoặc nới lỏng nhanh chóng giữa các hiệp tập.\n\nĐeo quanh thắt lưng (ngay trên xương hông), hít sâu gồng chặt cơ bụng rồi siết chặt đai trước các bài Squat, Deadlift, Barbell Row, Overhead Press nặng.\n\nBẢO QUẢN CHUẨN GYMER:\n- Lau sạch bụi bẩn và mồ hôi bằng khăn ẩm sau buổi tập.\n- Dán kín phần băng dán gai Velcro khi không sử dụng để bảo vệ lớp dán không bám bụi.\n- Treo nơi khô thoáng, không gập gãy đai.', 850000, 690000, 25, 'dai_lung_harbinger_4inch.jpg', 3, 7, 'unisex', 'S,M,L,XL', 'Đen', 'Nylon bọc xốp, khóa dán', NULL, 'giamcan,tangcan', NULL, 1, 1, 170, 62),
(21, 'Dây Kéo Lưng Lifting Straps Harbinger', 'Dây kéo lưng Lifting Straps Harbinger hỗ trợ tăng cường lực nắm tối đa khi thực hiện các bài kéo nặng, giải phóng áp lực cho cẳng tay và ngón tay. Sản xuất từ sợi Cotton bản dày 1.5 inch siêu bền bỉ kết hợp đệm mút Neoprene êm ái tại vị trí tiếp xúc cổ tay, hạn chế tối đa cảm giác siết đau rát da. Chiều dài dây mở rộng 21.5 inch cho phép quấn đòn tạ từ 2 đến 3 vòng chắc chắn, triệt tiêu hoàn toàn nỗi lo tuột tạ giữa chừng.\n\nLuồn dây qua cổ tay, quấn đầu dây còn lại quanh đòn tạ hoặc thanh đòn xà, siết chặt tay nắm vào dây trước khi nâng tạ trong các bài Deadlift, Shrug, Lat Pulldown, Dumbbell Row.\n\nBẢO QUẢN CHUẨN GYMER:\n- Giặt tay định kỳ bằng nước ấm và xà phòng loãng.\n- Phơi khô tự nhiên trong bóng mát, không dùng bàn ủi.', 250000, 190000, 60, 'day_keo_harbinger.jpg', 3, 7, 'unisex', NULL, 'Đen,Đỏ', 'Cotton bản dày, đệm cổ tay Neoprene', NULL, 'tangcan', NULL, 0, 1, 120, 40),
(22, 'Băng Quấn Gối Harbinger Knee Sleeves', 'Băng quấn gối Harbinger Knee Sleeves độ dày 5mm là trợ thủ đắc lực bảo vệ khớp gối cho gymer và vận động viên cử tạ. Chất liệu cao su Neoprene cao cấp đàn hồi cao giúp giữ ấm bao khớp, thúc đẩy tuần hoàn máu và cung cấp lực nén cơ học hỗ trợ bật dậy dễ dàng từ đáy bài Squat. Đường may 3D ôm sát theo cấu trúc giải phẫu học khớp gối, không bị xê dịch hay cộm cứng khi gập gối sâu.\n\nKéo băng quấn gối từ bàn chân lên sao cho tâm băng nằm chính giữa bánh chè đầu gối trước khi thực hiện Squat, Leg Press, Hack Squat, Lunge.\n\nBẢO QUẢN CHUẨN GYMER:\n- Sau buổi tập lộn ngược mặt trong của băng gối ra ngoài để hong khô mồ hôi.\n- Giặt tay bằng nước lạnh, không giặt máy.\n- Phơi khô trong bóng râm thoáng gió.', 520000, 420000, 32, 'bang_goi_harbinger.jpg', 3, 7, 'unisex', 'S,M,L,XL', 'Đen', 'Neoprene 5mm', NULL, 'giamcan,tangcan,duytri', NULL, 0, 1, 197, 42),
(23, 'Bình Lắc BlenderBottle Classic 28oz (820ml)', 'Bình lắc BlenderBottle Classic 28oz (dung tích 820ml) là mẫu bình lắc thể thao huyền thoại được tin dùng nhất trên thế giới. Sử dụng chất liệu nhựa Eastman Tritan cao cấp kháng ố và kháng mùi vượt trội, 100% không chứa BPA và Phthalate an toàn cho sức khỏe. Quả lắc kim loại BlenderBall làm từ thép không gỉ y tế 316 độc quyền, đánh tan mịn màng bột Whey, Mass, BCAA trong tích tắc. Nắp vặn ren StayOpen nắp bật chắc chắn không bao giờ chạm vào mũi khi uống.\n\nĐổ nước hoặc sữa tươi vào bình trước (nước nguội hoặc nước mát), cho bột protein vào, thả quả cầu BlenderBall vào và đậy nắp thật chặt, lắc đều trong 15-20 giây.\n\nBẢO QUẢN CHUẨN GYMER:\n- Rửa sạch ngay sau khi sử dụng bằng nước rửa chén thông thường.\n- An toàn khi rửa bằng khay trên cùng của máy rửa bát.\n- Không cho vào lò vi sóng, không dùng cho chất lỏng nóng trên 60°C.', 280000, 220000, 80, 'binh_lac_blender_classic.jpg', 4, 8, 'unisex', NULL, 'Đen,Trong Suốt,Xanh Navy', 'Nhựa Tritan không chứa BPA', NULL, 'giamcan,tangcan,duytri', NULL, 1, 1, 227, 75),
(24, 'Bình Lắc BlenderBottle ProStak 22oz (650ml)', 'Bình lắc BlenderBottle ProStak 22oz (650ml) tích hợp hệ thống ngăn chứa dinh dưỡng độc lập đa năng (All-in-one). Thân bình đi kèm 2 ngăn chứa vặn ren tháo rời (ngăn 150ml và ngăn 100ml) cùng khay chia viên nén tiện lợi, cho phép bạn mang theo đầy đủ Whey Protein, BCAA, Creatine và Vitamin cho cả ngày dài chỉ trong một chiếc bình duy nhất. Nắp đậy công nghệ Leak-Proof kín khít tuyệt đối, quả lắc lò xo inox 316 đánh tan bột siêu mịn.\n\nĐựng bột và viên uống vào các ngăn phụ bên dưới, khi đến giờ tập chỉ cần vặn mở và pha trực tiếp vào khoang chứa nước bên trên.\n\nBẢO QUẢN CHUẨN GYMER:\n- Tháo rời các ngăn khi vệ sinh để làm sạch từng chi tiết.\n- Mở nắp bình khi cất giữ trong tủ để bình luôn thoáng sạch, không lưu mùi.', 420000, 340000, 50, 'binh_lac_blender_prostak.jpg', 4, 8, 'unisex', NULL, 'Đen,Xám', 'Nhựa Tritan không chứa BPA', NULL, 'giamcan,tangcan,duytri', NULL, 0, 1, 57, 21),
(25, 'Bình Nước Thể Thao MyProtein 1 Lít', 'Bình nước thể thao MyProtein dung tích 1 Lít là giải pháp cấp nước hoàn hảo cho mọi buổi tập luyện cường độ cao. Sản xuất từ chất liệu nhựa nguyên sinh Polypropylene đạt chuẩn an toàn thực phẩm, không chứa BPA gây hại. Thiết kế nắp bật thể thao thông minh thao tác mở bằng một tay nhanh chóng, tích hợp khóa gài an toàn chống bung nắp khi để trong túi tập. Thân bình có vạch chia ml sắc nét giúp bạn theo dõi chính xác lượng nước nạp vào cơ thể mỗi ngày.\n\nĐựng nước lọc, nước bù điện giải, BCAA hoặc nước ép hoa quả uống từng ngụm nhỏ liên tục trong suốt buổi tập.\n\nBẢO QUẢN CHUẨN GYMER:\n- Vệ sinh bình hàng ngày bằng nước rửa chén và cọ mềm.\n- Không dùng để đựng nước sôi hoặc nước ngọt có gas trong thời gian dài.', 190000, 150000, 70, 'binh_nuoc_myprotein_1l.jpg', 4, 4, 'unisex', NULL, 'Đen,Xanh Dương,Trắng', 'Nhựa PP không chứa BPA', NULL, 'giamcan,tangcan,duytri', NULL, 0, 1, 201, 53),
(26, 'Khăn Tập Gym Microfiber Gymshark', 'Khăn tập gym Microfiber Gymshark kích thước chuẩn 40x80cm là phụ kiện giữ gìn vệ sinh không thể thiếu trong phòng tập. Dệt từ sợi Microfiber mật độ cao với khả năng thấm hút nước gấp 7 lần trọng lượng khăn và khô nhanh gấp 3 lần khăn cotton truyền thống. Mặt vải mềm mịn không gây kích ứng da mặt, tích hợp khuy bấm từ tính thông minh giúp bạn treo khăn dễ dàng lên thanh tạ hoặc máy tập mà không sợ rơi rớt xuống sàn bẩn.\n\nDùng để lau mồ hôi mặt, cổ và trải lên bề mặt đệm ghế tập gym trước khi nằm hoặc ngồi tập để đảm bảo vệ sinh cá nhân.\n\nBẢO QUẢN CHUẨN GYMER:\n- Giặt sạch khăn sau mỗi buổi tập bằng xà phòng thông thường.\n- Không dùng nước xả vải làm giảm độ thấm hút của sợi Microfiber.\n- Phơi nơi khô ráo, thoáng mát.', 220000, 170000, 65, 'khan_tap_gymshark.jpg', 4, 1, 'unisex', NULL, 'Đen,Xám', 'Microfiber', NULL, 'giamcan,tangcan,duytri', NULL, 0, 1, 76, 19),
(27, 'Túi Trống Tập Gym Under Armour Undeniable Duffle', 'Túi trống tập gym Under Armour Undeniable Duffle là người bạn đồng hành bền bỉ trên mọi chặng đường đến phòng tập và du lịch. Ứng dụng công nghệ xử lý bề mặt UA Storm chống thấm nước tối ưu, bảo vệ toàn bộ đồ đạc bên trong trước những cơn mưa bất chợt. Đáy và các mặt bên gia cố lớp lót chịu mài mòn cực cao. Bố trí ngăn thông gió riêng biệt cho giày tập và quần áo bẩn sau tập, ngăn kéo phụ kiện có khóa tiện lợi và quai đeo vai có đệm êm ái HeatGear.\n\nSắp xếp quần áo tập, giày gym, bình lắc, đai lưng và đồ vệ sinh cá nhân ngăn nắp trước khi đến phòng tập.\n\nBẢO QUẢN CHUẨN GYMER:\n- Lau sạch vết bẩn bằng khăn ẩm và xà phòng loãng.\n- Để túi mở cửa sổ thông gió định kỳ để túi luôn thơm tho.\n- Không giặt túi bằng máy giặt.', 1200000, 950000, 22, 'tui_trong_ua_duffle.jpg', 4, 5, 'unisex', NULL, 'Đen,Xám Đậm', 'Polyester chống thấm nước', NULL, 'giamcan,tangcan,duytri', NULL, 0, 1, 166, 54),
(28, 'Whey Protein Dymatize ISO100 Hydrolyzed 5Lbs (2.3kg)', 'Whey Protein Dymatize ISO100 Hydrolyzed 5Lbs (2.3kg) là đỉnh cao của dòng Whey Protein thủy phân tinh khiết bậc nhất hành tinh. Sản xuất qua quy trình lọc vi mô dòng chéo kết hợp công nghệ thủy phân Enzyme tiên tiến, loại bỏ hầu như toàn bộ tạp chất, đường lactose và chất béo. Mỗi muỗng cung cấp 25g Hydrolyzed Whey Isolate hấp thu ngay tức thì vào cơ bắp, 5.5g BCAA (trong đó 2.6g Leucine kích hoạt tổng hợp protein cơ bắp tối đa) và dưới 1g đường.\n\nPha 1 muỗng gạt (khoảng 30g-32g tùy vị) với 200 - 240ml nước lạnh hoặc sữa hạnh nhân không đường trong bình lắc, lắc đều trong 15 giây và uống ngay.\n\nTHỜI ĐIỂM SỬ DỤNG:\n- Ngay sau buổi tập trong vòng 30 phút để phục hồi cơ bắp thần tốc.\n- Sáng sớm sau khi ngủ dậy để chấm dứt trạng thái dị hóa cơ bắp ban đêm.\n\nBẢO QUẢN CHUẨN GYMER:\n- Đậy chặt nắp hộp sau khi dùng, bảo quản nơi khô ráo, thoáng mát dưới 25°C.', 2350000, 2090000, 20, 'whey_dymatize_iso100.jpg', 5, 9, 'unisex', NULL, 'Vị Chocolate,Vị Vani,Vị Dâu', NULL, 'Khoảng 25g Protein, 5g BCAA, dưới 1g đường, khoảng 110 Calories mỗi muỗng (30g)', 'tangcan,duytri', '2028-03-31', 1, 1, 118, 42),
(29, 'Sữa Tăng Cân Optimum Nutrition Serious Mass 12Lbs (5.4kg)', 'Sữa tăng cân Optimum Nutrition Serious Mass 12Lbs (5.4kg) là giải pháp dinh dưỡng hoàn hảo giúp người gầy lâu năm bứt phá cân nặng và kích thước cơ bắp. Mỗi khẩu phần chuẩn (2 muỗng lớn) mang đến nguồn năng lượng khổng lồ lên tới 1.250 Calories, 50g Protein phức hợp đa nguồn nuôi cơ bền bỉ và hơn 250g Carbohydrate phức hợp bổ sung glycogen dự trữ. Ngoài ra, sản phẩm còn được tăng cường thêm Creatine Monohydrate, Glutamine cùng 25 loại vitamin và khoáng chất thiết yếu.\n\nChia 1 khẩu phần (2 muỗng) làm 2 đến 3 lần uống rải đều trong ngày. Mỗi lần pha 1 muỗng với 400 - 500ml nước lọc hoặc sữa tươi nguyên kem trong bình lắc lớn hoặc máy xay sinh tố.\n\nTHỜI ĐIỂM SỬ DỤNG:\n- Giữa bữa sáng và bữa trưa (khoảng 9h30 - 10h).\n- Ngay sau buổi tập 30 - 45 phút.\n- Trước khi đi ngủ 1 tiếng.\n\nBẢO QUẢN CHUẨN GYMER:\n- Để bịch sữa nơi khô ráo thoáng mát, buộc chặt miệng túi hoặc san ra hộp kín nắp.', 1950000, 1690000, 18, 'mass_on_serious_mass.jpg', 5, 3, 'unisex', NULL, 'Vị Chocolate,Vị Vani', NULL, 'Khoảng 1250 Calories, 50g Protein, 250g Carb mỗi 2 muỗng lớn (334g), bổ sung Creatine và vitamin', 'tangcan', '2028-01-31', 0, 1, 290, 107),
(30, 'Whey Protein MyProtein Impact Whey 2.5kg', 'Whey Protein MyProtein Impact Whey 2.5kg là dòng bột đạm cao cấp được yêu chuộng bậc nhất tại thị trường Châu Âu nhờ chất lượng vượt trội cùng mức giá cực kỳ kinh tế. Được chiết xuất 100% từ nguồn sữa bò ăn cỏ tự nhiên, mỗi khẩu phần (1 muỗng 25g) cung cấp 21g Protein chất lượng cao, 4.5g BCAA tự nhiên và lượng calo chỉ khoảng 103 kcal. Đa dạng hương vị thơm ngon dễ uống, độ hòa tan tuyệt vời, đáp ứng trọn vẹn nhu cầu bổ sung đạm hàng ngày cho mọi người tập thể thao.\n\nPha 1 muỗng (25g) với 150 - 250ml nước lạnh hoặc sữa tươi trong bình lắc, lắc đều 15 giây và uống ngay.\n\nTHỜI ĐIỂM SỬ DỤNG:\n- Sau buổi tập trong vòng 30 - 60 phút.\n- Uống giữa các bữa ăn chính như bữa phụ dinh dưỡng tiện lợi.\n\nBẢO QUẢN CHUẨN GYMER:\n- Kéo kín miệng túi ziplock sau khi lấy bột, bảo quản nơi khô thoáng dưới 25°C.', 1450000, 1190000, 28, 'whey_myprotein_impact.jpg', 5, 4, 'unisex', NULL, 'Vị Chocolate,Vị Vani,Vị Dâu', NULL, 'Khoảng 21g Protein, 4g BCAA, 103 Calories mỗi muỗng (25g)', 'tangcan,duytri', '2028-02-28', 0, 1, 176, 54),
(31, 'Creatine Monohydrate MuscleTech Platinum 100% 400g', 'Creatine Monohydrate MuscleTech Platinum 100% 400g cung cấp nguồn Creatine Monohydrate siêu tinh khiết được kiểm định qua quy trình HPLC khắt khe. Creatine đóng vai trò như một nguồn năng lượng tái tạo ATP dự trữ trong mô cơ, giúp gia tăng sức mạnh bộc phát, nâng cao sức bền cơ bắp và đẩy tăng số reps trong các bài tập tạ nặng. Đồng thời, Creatine hút nước vào nội bào tế bào cơ, tạo hiệu ứng căng phồng cơ bắp (Muscle Cell Volumization) và thúc đẩy tăng trưởng cơ nhanh chóng.\n\nPha 1 muỗng gạt (5g) với 250 - 300ml nước lọc, nước trái cây hoặc pha chung vào bình Whey Protein sau tập.\n\nLỊCH DÙNG KHUYẾN NGHỊ:\n- Cách 1 (Nạp duy trì): Uống đều đặn 5g mỗi ngày (sau tập hoặc buổi sáng ngày nghỉ).\n- Cách 2 (Giai đoạn nạp nhanh): Uống 20g/ngày (chia làm 4 lần x 5g) trong 5 ngày đầu, sau đó duy trì 5g/ngày.\n* Lưu ý: Luôn uống đủ từ 2.5 đến 3.5 lít nước mỗi ngày khi sử dụng Creatine.\n\nBẢO QUẢN CHUẨN GYMER:\n- Đậy chặt nắp hộp, bảo quản nơi khô ráo, tránh ẩm vì Creatine dễ vón cục nếu gặp không khí ẩm.', 690000, 550000, 35, 'creatine_muscletech_400g.jpg', 5, 11, 'unisex', NULL, 'Không Vị', NULL, '5g Creatine Monohydrate mỗi lần dùng, khoảng 80 lần dùng mỗi hộp', 'tangcan,duytri', '2028-06-30', 1, 1, 180, 69),
(32, 'BCAA Applied Nutrition Amino-Hydrate 450g', 'BCAA Applied Nutrition Amino-Hydrate 450g là công thức bù nước và điện giải trong tập (Intra-workout) được thiết kế cho các vận động viên và gymer tập cường độ cao. Cung cấp 7.2g BCAA tỉ lệ vàng 2:1:1 (Leucine, Isoleucine, Valine) ngăn ngừa dị hóa mất cơ bắp khi tập nặng, kết hợp cùng 3g Glutamine chống mỏi cơ và phức hợp khoáng chất điện giải Electrolytes bù đắp tức thì lượng muối khoáng thất thoát qua mồ hôi, ngăn ngừa chuột rút và duy trì thể lực dẻo dai.\n\nPha 1 muỗng (14g) với 500ml nước lạnh trong bình lắc, thêm đá lạnh nếu thích. Lắc đều và nhâm nhi từng ngụm nhỏ trong suốt buổi tập luyện.\n\nTHỜI ĐIỂM SỬ DỤNG:\n- Nhâm nhi trong lúc tập luyện (Intra-workout) hoặc uống trong những ngày nắng nóng mất nhiều mồ hôi.\n\nBẢO QUẢN CHUẨN GYMER:\n- Đậy chặt nắp hộp sau khi dùng, bảo quản nơi khô ráo thoáng mát.', 650000, 520000, 30, 'bcaa_applied_amino_hydrate.jpg', 5, 10, 'unisex', NULL, 'Vị Cam,Vị Dưa Hấu,Vị Chanh Dây', NULL, 'BCAA tỉ lệ 2:1:1 (Leucine, Isoleucine, Valine), Glutamine, chất điện giải', 'giamcan,duytri', '2028-04-30', 0, 1, 87, 27),
(33, 'Pre-Workout Applied Nutrition ABE 315g', 'Pre-Workout Applied Nutrition ABE (All Black Everything) 315g là dòng bột tăng lực trước tập bán chạy số 1 tại Vương quốc Anh. Sự kết hợp bùng nổ giữa 200mg Caffeine kích hoạt sự tỉnh táo tập trung cao độ, 2g Beta-Alanine giảm tích tụ axit lactic chống mỏi cơ, 4g Tri-Creatine Blend gia tăng sức mạnh bộc phát và 4g Citrulline Malate bơm căng cơ bắp (Muscle Pump) và giãn mạch máu tối đa. Thêm thành phần vitamin B3, B12 hỗ trợ chuyển hóa năng lượng không ngừng nghỉ.\n\nPha 1 muỗng gạt (10.5g) với 250ml nước lạnh trong bình lắc. Lắc đều và uống trước khi bước vào buổi tập từ 20 đến 30 phút.\n\nLƯU Ý QUAN TRỌNG:\n- Cảm giác ngứa ran nhẹ trên da (do Beta-Alanine) là hiện tượng hoàn toàn tự nhiên và vô hại.\n- Người mới dùng nên bắt đầu với 1/2 muỗng để làm quen với hàm lượng Caffeine.\n- Không dùng quá 1 muỗng trong 24 giờ và không uống trước giờ đi ngủ trong vòng 6 tiếng.\n\nBẢO QUẢN CHUẨN GYMER:\n- Đậy thật chặt nắp hộp sau mỗi lần mở nắp để chống vón cục.', 780000, 650000, 26, 'pre_applied_abe.jpg', 6, 10, 'unisex', NULL, 'Vị Cherry Cola,Vị Táo Xanh', NULL, 'Caffeine, Beta-Alanine, L-Citrulline, Taurine, Vitamin nhóm B', 'tangcan,duytri', '2028-02-29', 1, 1, 118, 39),
(34, 'Hydroxycut Hardcore Elite MuscleTech 100 Viên', 'Viên đốt mỡ Hydroxycut Hardcore Elite MuscleTech 100 Viên là sản phẩm sinh nhiệt đốt mỡ danh tiếng hàng đầu thế giới dành riêng cho gymer trong giai đoạn Cutting siết cơ giảm mỡ. Công thức độc quyền kết hợp Caffeine Anhydrous hàm lượng cao, chiết xuất cà phê xanh chuẩn hóa CGA, chiết xuất trà xanh, thảo dược Yohimbe và L-Theanine. Sản phẩm thúc đẩy đốt cháy calo thừa, tăng cường trao đổi chất và nâng cao sự tập trung trong các buổi tập Cardio cường độ cao.\n\nUống trước bữa ăn chính từ 30 đến 60 phút cùng 1 ly nước lớn.\n\nHƯỚNG DẪN LÀM QUEN:\n- Ngày 1 & 2: Uống 1 viên/ngày vào buổi sáng.\n- Ngày 3 & 4: Uống 2 viên/ngày (1 viên sáng, 1 viên trước tập).\n- Từ ngày 5 trở đi: Uống tối đa 2 viên/lần x 2 lần/ngày (cách nhau ít nhất 4 tiếng).\n* Không uống trong vòng 5 tiếng trước khi ngủ. Uống đủ 2.5 - 3 lít nước mỗi ngày.\n\nBẢO QUẢN CHUẨN GYMER:\n- Đậy kín nắp, bảo quản nơi khô ráo, tránh nhiệt độ cao và xa tầm tay trẻ em.', 750000, 620000, 24, 'dotmo_muscletech_hydroxycut.jpg', 6, 11, 'unisex', NULL, 'Hộp 100 viên', NULL, 'Caffeine Anhydrous, chiết xuất trà xanh, L-Theanine', 'giamcan', '2028-05-31', 0, 1, 206, 60),
(35, 'Amino Energy Optimum Nutrition 270g (30 Lần Dùng)', 'Amino Energy Optimum Nutrition 270g (30 Lần Dùng) là sự pha trộn hoàn hảo giữa nguồn Amino Acid thiết yếu phục hồi cơ bắp và Caffeine tự nhiên chiết xuất từ hạt cà phê xanh và lá trà xanh. Mỗi khẩu phần cung cấp 5g chuỗi Amino Acid tinh khiết hỗ trợ xây dựng cơ bắp cùng 100mg Caffeine giúp tinh thần tỉnh táo, sảng khoái và tràn đầy năng lượng mà không gây cảm giác say hay bồn chồn tim đập nhanh. Hàm lượng calo chỉ 10 kcal và hoàn toàn không chứa đường.\n\nPha 2 muỗng gạt (9g) với 300 - 350ml nước lạnh. Có thể thêm đá lạnh để tăng thêm vị ngon sảng khoái.\n\nTHỜI ĐIỂM SỬ DỤNG ĐA NĂNG:\n- Buổi sáng thay thế cho cà phê thông thường.\n- Trước buổi tập 20 - 30 phút để nạp năng lượng tập luyện.\n- Buổi chiều khi làm việc mệt mỏi cần sự tỉnh táo tập trung.\n\nBẢO QUẢN CHUẨN GYMER:\n- Đậy chặt nắp sau khi mở, bảo quản nơi khô ráo, thoáng mát.', 640000, 520000, 33, 'amino_on_energy.jpg', 6, 3, 'unisex', NULL, 'Vị Cam,Vị Dâu,Vị Trái Cây Hỗn Hợp', NULL, 'Khoảng 5g Amino Acid, khoảng 100mg Caffeine mỗi lần dùng (9g)', 'giamcan,duytri', '2028-01-31', 0, 1, 107, 31),
(36, 'Vitamin Tổng Hợp Optimum Nutrition Opti-Men 90 Viên', 'Vitamin Tổng Hợp Optimum Nutrition Opti-Men 90 Viên là công thức dinh dưỡng vi lượng toàn diện được thiết kế riêng biệt cho nhu cầu thể lực của nam giới năng động và gymer tập nặng. Cung cấp hơn 75 hoạt chất thiết yếu phân thành 4 nhóm hỗ trợ chuyên sâu: Nhóm Amino-Blend xây dựng cơ bắp, nhóm Phyto-Blend chiết xuất từ thực vật chống oxy hóa, nhóm Viri-Blend tăng cường sinh lực nam và nhóm Enzy-Blend enzyme hỗ trợ hệ tiêu hóa hấp thu dinh dưỡng tối đa. Đáp ứng 100% nhu cầu vitamin khoáng chất hàng ngày.\n\nUống 3 viên mỗi ngày sau các bữa ăn chính (có thể uống 1 viên sau bữa sáng, 1 viên sau bữa trưa và 1 viên sau bữa tối) cùng nhiều nước.\n\nLƯU Ý:\n- Uống nhiều nước trong ngày (tối thiểu 2 - 2.5 lít).\n- Nước tiểu có màu vàng sáng là hiện tượng đào thải vitamin nhóm B hòa tan trong nước dư thừa hoàn toàn tự nhiên và an toàn.\n\nBẢO QUẢN CHUẨN GYMER:\n- Đậy chặt nắp hộp, bảo quản nơi khô mát dưới 25°C, tránh ánh nắng trực tiếp.', 690000, 560000, 30, 'vitamin_on_opti_men.jpg', 7, 3, 'nam', NULL, 'Hộp 90 viên', NULL, 'Vitamin A, C, D, E, nhóm B, khoáng chất, hỗn hợp Amino Acid', 'tangcan,duytri', '2028-04-30', 0, 1, 172, 68),
(37, 'Vitamin Tổng Hợp Optimum Nutrition Opti-Women 120 Viên', 'Vitamin Tổng Hợp Optimum Nutrition Opti-Women 120 Viên là sản phẩm bổ sung vi chất dinh dưỡng thiết kế chuyên biệt cho phụ nữ hiện đại và gymer nữ tập luyện thể thao. Chứa hơn 40 thành phần hoạt tính, bao gồm 23 loại vitamin và khoáng chất thiết yếu, tăng cường hàm lượng Sắt (Iron) hỗ trợ tạo máu và Canxi kết hợp Vitamin D giúp xương chắc khỏe dẻo dai. Bổ sung Axit Folic, chiết xuất đậu nành Isoflavones và thảo mộc tự nhiên giúp cân bằng nội tiết tố nữ, nuôi dưỡng làn da, mái tóc và móng khỏe đẹp từ bên trong.\n\nUống 2 viên mỗi ngày cùng bữa ăn (uống 1 viên sau bữa sáng và 1 viên sau bữa trưa) cùng một ly nước lớn.\n\nBẢO QUẢN CHUẨN GYMER:\n- Đậy kín nắp lọ, bảo quản nơi khô ráo, thoáng mát và tránh nhiệt độ cao.', 640000, 520000, 28, 'vitamin_on_opti_women.jpg', 7, 3, 'nu', NULL, 'Hộp 120 viên', NULL, 'Vitamin A, C, D, E, nhóm B, Sắt, Canxi, Folate', 'giamcan,duytri', '2028-04-30', 0, 1, 155, 47),
(38, 'Omega-3 Now Foods 1000mg 200 Viên', 'Dầu Cá Omega-3 Now Foods 1000mg 200 Viên cung cấp nguồn axit béo không no thiết yếu EPA và DHA được chiết xuất từ các loài cá biển sâu tinh khiết. Áp dụng quy trình chưng cất phân tử nghiêm ngặt đạt chuẩn GMP Hoa Kỳ, loại bỏ hoàn toàn thủy ngân, kim loại nặng và độc tố dioxin. Mỗi liều dùng cung cấp 180mg EPA và 120mg DHA hỗ trợ tối ưu cho sức khỏe tim mạch, bôi trơn các khớp xương chống đau mỏi khi tập tạ nặng, giảm phản ứng viêm cơ bắp và hỗ trợ cải thiện thị lực, não bộ.\n\nUống 2 viên mỗi ngày, dùng 1 đến 2 lần cùng với bữa ăn chính chứa chất béo tốt để tăng cường khả năng hấp thu.\n\nBẢO QUẢN CHUẨN GYMER:\n- Bảo quản nơi khô ráo, thoáng mát sau khi mở nắp, tránh ánh nắng mặt trời trực tiếp.', 560000, 450000, 40, 'omega3_now_foods.jpg', 7, 12, 'unisex', NULL, 'Hộp 200 viên', NULL, 'Dầu cá (EPA, DHA), Vitamin E', 'giamcan,duytri', '2028-08-31', 0, 1, 164, 35),
(39, 'Vitamin D3 Now Foods 5000 IU 240 Viên', 'Vitamin D3 Now Foods 5000 IU 240 Viên cung cấp dạng vitamin D3 (Cholecalciferol) hoạt tính cao với sinh khả dụng tối đa, tan trong chất béo dạng viên nang mềm tiện lợi. Vitamin D3 đóng vai trò tối quan trọng giúp tăng cường hấp thu canxi và photpho vào hệ xương khớp, nâng cao mật độ xương chắc khỏe chịu tải mức tạ nặng, đồng thời củng cố hệ miễn dịch tự nhiên của cơ thể và duy trì nồng độ testosterone nội sinh tối ưu cho sự phát triển của cơ bắp.\n\nUống 1 viên nang mềm mỗi ngày (hoặc cách ngày) cùng bữa ăn có chứa chất béo (như bữa ăn có trứng, bơ, dầu ô liu hoặc uống cùng Omega-3).\n\nBẢO QUẢN CHUẨN GYMER:\n- Đậy kín nắp lọ sau khi lấy viên uống.\n- Bảo quản nơi khô ráo, thoáng mát dưới 25°C, tránh ánh sáng trực tiếp.', 420000, 340000, 39, 'vitamin_d3_now_foods.jpg', 7, 12, 'unisex', NULL, 'Hộp 240 viên', NULL, 'Vitamin D3 (Cholecalciferol) 5000 IU mỗi viên, dầu ô liu', 'tangcan,duytri', '2028-10-31', 0, 1, 109, 28);
